import json
from IPython.display import HTML


with open('coefs.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

data_json = json.dumps(data)

htmlCode = f"""
&lt;head&gt;
    &lt;style&gt;
        .grid {{ display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; max-width: 600px; margin: auto; }}
        input {{ width: 100%; padding: 6px; box-sizing: border-box; }}
        .button {{ grid-column: 1 / -1; padding: 10px; text-align: center; }}
        .output {{ grid-column: 1 / -1; padding: 10px; text-align: center; font-weight: bold; }}
    &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;

    &lt;div class="grid"&gt;
        &lt;label&gt;Current Bikes&lt;/label&gt;
        &lt;label&gt;Time&lt;/label&gt;
        &lt;label&gt;Station&lt;/label&gt;

        &lt;input type="number" id="num" value="10"&gt;
        &lt;input type="datetime-local" id="date"&gt;
        &lt;input type="text" id="name" list="listEl" placeholder="Search..." value="Ympyrätalo"&gt;

        &lt;button id="button" class="button" onclick="calc()"&gt;Caculate&lt;/button&gt;

        &lt;div id="out" class="output"&gt;&lt;/div&gt;
    &lt;/div&gt;

    &lt;datalist id="listEl"&gt;&lt;/datalist&gt;

    &lt;script&gt;
        const data = {data_json};
        const list = [...new Set(Object.keys(data.coefficients).map(key =&gt; key.split('_')[0]))]
        const listEl = document.getElementById('listEl');
        let options = '';
        for (let n of list) {{
            options += '&lt;option value="' + n + '"&gt;' + n + '&lt;/option&gt;';
        }}

        listEl.innerHTML = options;
        document.getElementById('date').value = new Date(2026, 6, 6, 11, 0).toISOString().slice(0, 16);
        const getWeekOfYear = (d) =&gt; {{
            const target = new Date(d.valueOf());
            const dayNr = (d.getDay() + 6) % 7;
            target.setDate(target.getDate() - dayNr + 3);
            const firstThursday = target.valueOf();
            target.setMonth(0, 1);
            if (target.getDay() !== 4) {{
                target.setMonth(0, 1 + ((4 - target.getDay()) + 7) % 7);
            }}
            return Math.ceil((firstThursday - target) / (7 * 24 * 60 * 60 * 1000)) + 1;
        }};

        function calc() {{
            const intercept = data.intercept 
            const date = (new Date(document.getElementById('date').value))
            const bikes = (parseFloat(document.getElementById('num').value) || 0)
            const station = (document.getElementById('name').value.trim())
            const hour = `${{station}}_h${{(date.getHours() || 0)}}`
            const day = `${{station}}_d${{((date.getDay() + 6) % 7 || 0)}}`
            const week = `${{station}}_w${{(getWeekOfYear(date) || 0)}}`

            const y = intercept + data.coefficients[hour] + data.coefficients[day] + data.coefficients[week]
            const txt = "CEstimated change in station bike amount in next hr ="


            document.getElementById('out').innerText = `${{txt}} ${{y.toFixed(1)}} (${{(bikes + y).toFixed(1)}} bikes)`;

        }}
    &lt;/script&gt;
&lt;/body&gt;
"""

HTML(htmlCode)









